//! Shared helpers for the golden differential tests (fixtures generated by
//! `go run -mod=vendor ./hack/golden/gocompat`).
#![allow(dead_code)]

use serde_json::{Map, Number, Value};
use sha2::{Digest, Sha256};

pub fn fixture(name: &str) -> Value {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    let data = std::fs::read(&path).unwrap_or_else(|e| panic!("reading {path}: {e}"));
    serde_json::from_slice(&data).unwrap_or_else(|e| panic!("parsing {path}: {e}"))
}

pub fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex"))
        .collect()
}

pub fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

pub fn sha256_hex(b: &[u8]) -> String {
    hex(&Sha256::digest(b))
}

pub fn opt_str(v: &Value) -> Option<String> {
    v.as_str().map(|s| s.to_string())
}

/// Decodes the typed value encoding written by the Go generator.
pub fn dec(v: &Value) -> Value {
    let a = v.as_array().expect("typed value");
    match a[0].as_str().expect("tag") {
        "n" => Value::Null,
        "b" => Value::Bool(a[1].as_bool().expect("bool")),
        "i" => Value::Number(Number::from(a[1].as_str().expect("i").parse::<i64>().expect("i64"))),
        "u" => Value::Number(Number::from(a[1].as_str().expect("u").parse::<u64>().expect("u64"))),
        "f" => {
            let bits = u64::from_str_radix(a[1].as_str().expect("f"), 16).expect("bits");
            Value::Number(Number::from_f64(f64::from_bits(bits)).expect("finite"))
        }
        "s" => Value::String(String::from_utf8(unhex(a[1].as_str().expect("s"))).expect("utf8")),
        "a" => Value::Array(a[1].as_array().expect("arr").iter().map(dec).collect()),
        "o" => {
            let mut m = Map::new();
            for e in a[1].as_array().expect("obj") {
                let kv = e.as_array().expect("kv");
                let k = String::from_utf8(unhex(kv[0].as_str().expect("k"))).expect("utf8");
                m.insert(k, dec(&kv[1]));
            }
            Value::Object(m)
        }
        t => panic!("unknown tag {t}"),
    }
}

/// Exact structural equality, comparing floats by bits.
pub fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => {
            if x.is_f64() || y.is_f64() {
                x.as_f64().map(f64::to_bits) == y.as_f64().map(f64::to_bits)
            } else {
                x == y
            }
        }
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| same(v, w)))
        }
        _ => a == b,
    }
}

/// splitmix64, mirrored from the Go generator.
pub struct Sm(pub u64);

impl Sm {
    pub fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
}

const WORDS: &[&str] = &[
    "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog", "ignition", "systemd", "unit", "{", "}", "\"",
    ":", ",", "\n", "  ", "storage", "files", "contents", "source", "data", "base64", "version", "3.4.0", "0644",
    "/etc/", "kubernetes", "\t", "a", "b", "c",
];

/// Deterministic payloads, mirrored from the Go generator's `payload`.
pub fn payload(kind: &str, seed: u64, size: usize) -> Vec<u8> {
    let mut r = Sm(seed);
    let mut out: Vec<u8> = Vec::with_capacity(size);
    match kind {
        "random" => {
            while out.len() < size {
                out.push(r.next() as u8);
            }
        }
        "zeros" => out = vec![0; size],
        "text" => {
            while out.len() < size {
                let w = WORDS[(r.next() % WORDS.len() as u64) as usize];
                out.extend_from_slice(w.as_bytes());
                out.push(b' ');
            }
        }
        "repeat" => {
            let n = 1 + r.next() % 61;
            let pat: Vec<u8> = (0..n).map(|_| r.next() as u8).collect();
            while out.len() < size {
                out.extend_from_slice(&pat);
            }
        }
        "lowentropy" => {
            while out.len() < size {
                out.push(b"acgt"[(r.next() % 4) as usize]);
            }
        }
        "mixed" => {
            while out.len() < size {
                let n = (1 + r.next() % 5000) as usize;
                match r.next() % 4 {
                    0 => {
                        for _ in 0..n {
                            out.push(r.next() as u8);
                        }
                    }
                    1 => out.extend(std::iter::repeat_n(0u8, n)),
                    2 => {
                        let mut n = n as i64;
                        while out.len() < size && n > 0 {
                            let w = WORDS[(r.next() % WORDS.len() as u64) as usize];
                            out.extend_from_slice(w.as_bytes());
                            n -= w.len() as i64;
                        }
                    }
                    _ => {
                        if !out.is_empty() {
                            let start = (r.next() % out.len() as u64) as usize;
                            let mut i = 0;
                            while i < n && start + i < out.len() {
                                let c = out[start + i];
                                out.push(c);
                                i += 1;
                            }
                        }
                    }
                }
            }
        }
        k => panic!("unknown payload kind {k}"),
    }
    out.truncate(size);
    out
}

/// Runs `f` on a thread with a large stack (for deeply nested inputs).
pub fn big_stack<F: FnOnce() + Send + 'static>(f: F) {
    std::thread::Builder::new()
        .stack_size(1 << 30)
        .spawn(f)
        .expect("spawn")
        .join()
        .expect("join");
}
